<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../../includes/planeaciones_service.php';
if(!tienePermiso('ver_planeaciones') && !tienePermiso('revisar_planeaciones')){http_response_code(403);exit('Acceso denegado.');}
try{$o=cufaOrigenPlan(is_string($_GET['origen']??null)?$_GET['origen']:'');$id=cufaId($_GET,['id']);
if($_SERVER['REQUEST_METHOD']==='POST'){validarPermiso('revisar_planeaciones');cufaValidarToken();cufaRevisarPlan($pdo,$o,$id,(string)($_POST['accion']??''),is_string($_POST['observaciones']??null)?$_POST['observaciones']:'',(int)$_SESSION['user_id']);}
$p=cufaPlan($pdo,$o,$id);}catch(Throwable $e){cufaError($e);return;}
?>
<div class="bg-white p-8 rounded-3xl shadow"><h1 class="text-3xl font-bold mb-5">Detalle de planeación</h1><p><?= cufaEsc($p['docente'].' · '.$p['materia'].' · '.$p['grupo'].' · '.$p['periodo']) ?></p><p>Origen: <?= cufaEsc($p['origen']) ?> #<?= $id ?> · Estado: <strong><?= cufaEsc($p['estado']) ?></strong></p>
<?php foreach(['semana'=>'Semana','tema'=>'Tema','objetivo'=>'Objetivo','descripcion'=>'Descripción / subtemas','actividad_nombre'=>'Actividad','actividades'=>'Actividades didácticas','observaciones'=>'Observaciones de revisión'] as $campo=>$label): ?><h2 class="font-bold mt-5"><?= $label ?></h2><p class="whitespace-pre-wrap"><?= nl2br(cufaEsc($p[$campo]??'Sin información')) ?></p><?php endforeach; ?>
<?php foreach(['material'=>'Material','archivo'=>'Archivo / rúbrica'] as $campo=>$label): $url=cufaArchivoPlan($p,$campo);if($url): ?><p class="mt-5"><a href="<?= cufaEsc($url) ?>" target="_blank" rel="noopener" class="text-purple-700 underline"><?= $label ?></a></p><?php endif; endforeach; ?>
<?php if(tienePermiso('revisar_planeaciones')): ?><form method="POST" class="mt-8 space-y-4" onsubmit="return confirm('¿Confirmas el resultado de revisión? Se conservará un historial de la acción.');"><input type="hidden" name="cufa_csrf" value="<?= cufaEsc(cufaToken()) ?>"><label>Observaciones<textarea name="observaciones" class="border p-4 w-full rounded-xl"><?= cufaEsc($p['observaciones']) ?></textarea></label><div class="flex flex-wrap gap-3"><button name="accion" value="aprobado" class="bg-emerald-600 text-white p-3 rounded-xl">Aprobar</button><button name="accion" value="rechazado" class="bg-red-600 text-white p-3 rounded-xl">Rechazar</button><button name="accion" value="devuelto" class="bg-amber-600 text-white p-3 rounded-xl">Devolver para corregir</button></div><p class="text-sm">Rechazar o devolver requiere observaciones. Devolver habilita nuevamente la edición docente.</p></form><?php endif; ?></div>
